<?php

namespace Tests\Unit;

use App\Services\Detections\SubmissionTask;
use PHPUnit\Framework\Attributes\DataProvider;
use Tests\TestCase;

class ExplicitAiRoutingTest extends TestCase
{
    public static function originRequests(): array
    {
        return array_map(fn ($text) => [$text], [
            'check if ai generated', 'please check whether this is AI-generated',
            'Analyze whether the attached picture was generated by artificial intelligence.',
            'Here is my upload. Please check if it is AI generated.',
            'Detect AI generation in this image.', 'AI check', 'AI-generated?',
            'Check this image for signs of AI generation and explain the result.',
            'Fact-check if this image is AI-generated.',
            'Is this uploaded face image AI-generated?',
            'Check whether this photo of two people is AI-generated.',
            'Is this AI-generated or real?', 'Is this a deepfake?',
            'Paki-check kung AI-generated ito.', 'AI ba ito?', 'Gawa ba ito ng AI?',
            'Check if this is A.I. generated.', 'Check if this is AIgenerated.',
        ]);
    }

    #[DataProvider('originRequests')]
    public function test_direct_origin_requests_override_a_selected_fact_check_mode(string $prompt): void
    {
        foreach (['image', 'video'] as $type) {
            $context = ['caption_text' => $prompt, 'analysis_task' => 'claim', 'media_type' => $type];
            $request = SubmissionTask::resolve($context, ['analysis_text' => 'The fictional library opened in 2024.']);
            $this->assertSame('media', $request['resolved_task'], $prompt);
            $this->assertSame(['media'], $request['tasks'], $prompt);
        }
    }

    public function test_a_long_fact_check_guide_or_notes_do_not_hide_an_ai_request(): void
    {
        foreach ([SubmissionTask::CLAIM_INSTRUCTION, SubmissionTask::SOURCES_INSTRUCTION, SubmissionTask::CONTEXT_INSTRUCTION] as $guide) {
            foreach ([['caption_text' => $guide.".\n\nCheck if this is AI-generated."],
                ['caption_text' => $guide.'.', 'notes' => 'Please check if the image is AI-generated.']] as $input) {
                $request = SubmissionTask::resolve($input + ['analysis_task' => 'claim', 'media_type' => 'image']);
                $this->assertSame('media', $request['resolved_task']);
                $this->assertSame(['media'], $request['tasks']);
                $this->assertStringNotContainsString('Prioritize', $request['question']);
            }
        }
    }

    public static function factualRequests(): array
    {
        return array_map(fn ($text) => [$text], [
            'Did the mayor ban AI-generated images?',
            'Fact-check whether the mayor used AI in the election.',
            'Is AI dangerous?',
            'Fact-check this claim: AI-generated images are prohibited in schools.',
            'Do not check if this is AI-generated. Verify the caption instead.',
            'The fictional council discussed AI-generated images in 2024.',
        ]);
    }

    #[DataProvider('factualRequests')]
    public function test_an_ai_topic_or_negated_ai_instruction_does_not_request_a_detector(string $prompt): void
    {
        $context = ['caption_text' => $prompt, 'analysis_task' => 'claim', 'media_type' => 'image'];
        $this->assertNotContains('media', SubmissionTask::tasks($context));
        $this->assertSame('claim', SubmissionTask::primary($context));
    }

    public function test_explicit_separate_factual_questions_remain_separate_tasks(): void
    {
        $context = ['caption_text' => 'Verify this claim. Also check if this image is AI-generated.',
            'analysis_task' => 'claim', 'media_type' => 'image'];
        $this->assertSame(['media', 'claim'], SubmissionTask::tasks($context));
        $this->assertSame('media', SubmissionTask::primary($context));
    }
}
